const text = String($json.text || '').trim();
let intent = 'chat';
if (/gasto|despesa|paguei|comprei|conta|pagar|lan[cç]ar|r\$|\d+[.,]\d{2}/i.test(text)) intent = 'finance';
else if (/c[oó]digo|gera(r)?\s*c[oó]digo|ativa[cç][aã]o|king[-_\s]?[a-z0-9]/i.test(text)) intent = 'code';
else if (/sentry|erro|bug|diagn[oó]stico|health|caiu|status|site/i.test(text)) intent = 'diag';

let amount = null;
const am = text.match(/r\$\s*(\d+[.,]?\d*)/i) || text.match(/(\d+[.,]\d{2})/) || text.match(/\b(\d{1,6})\b/);
if (am) amount = parseFloat(String(am[1]).replace(',', '.'));

let type = 'EXPENSE';
if (/receita|recebi|entrou|ganhei/i.test(text)) type = 'INCOME';
let status = 'PENDING';
if (/paguei|pago|já\s*paguei|ja\s*paguei/i.test(text)) status = 'PAID';

let description = text.replace(/r\$\s*\d+[.,]?\d*/ig, '').replace(/\s+/g, ' ').trim().slice(0, 180) || 'Lançamento via Telegram';

let customCode = '';
const cm = text.match(/\b(KING[-_\s]?[A-Z0-9]+)\b/i) || text.match(/c[oó]digo[^A-Za-z0-9]*([A-Z0-9][-_A-Z0-9]{2,})/i);
if (cm) customCode = String(cm[1]).replace(/\s+/g, '').toUpperCase().slice(0, 32);

const today = new Date().toISOString().slice(0, 10);
return [{ json: { ...$json, intent, amount, type, status, description, customCode, transactionDate: today } }];

const prev = $input.first().json;
const base = String($env.CK_BASE_URL || 'https://www.conectaking.com.br').replace(/\/$/, '');
const token = String($env.CK_AGENT_JWT || '').trim();
const openaiKey = String($env.OPENAI_API_KEY || '').trim();
const model = String($env.OPENAI_MODEL || 'gpt-4o-mini').trim();
const intent = prev.intent;

async function http(method, url, body, headers) {
  const opts = {
    method,
    url,
    headers: Object.assign({ Accept: 'application/json', 'Content-Type': 'application/json' }, headers || {}),
    json: true,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
  };
  if (body !== undefined) opts.body = body;
  return this.helpers.httpRequest.call(this, opts);
}

async function ck(method, path, body) {
  return http.call(this, method, base + path, body, token ? { Authorization: 'Bearer ' + token } : {});
}

async function openaiChat(system, user) {
  if (!openaiKey) return null;
  const r = await http.call(this, 'POST', 'https://api.openai.com/v1/chat/completions', {
    model,
    temperature: 0.4,
    max_tokens: 550,
    messages: [
      { role: 'system', content: system },
      { role: 'user', content: user },
    ],
  }, { Authorization: 'Bearer ' + openaiKey });
  if (!(r.statusCode >= 200 && r.statusCode < 300)) {
    return 'OpenAI erro (' + r.statusCode + '): ' + JSON.stringify(r.body).slice(0, 220);
  }
  return String(r.body?.choices?.[0]?.message?.content || '').trim();
}

const ADMIN_SYSTEM = `Você é o Assistente Executivo do Conecta King (Telegram) do Adriano King.\nFale em português do Brasil, direto e profissional.\n\nAções que o sistema executa automaticamente (não invente que fez se não veio confirmação):\n- Lançar despesa/receita na Gestão Financeira\n- Gerar código ADM (ex.: KING-XXXX)\n- Diagnóstico/health do site\n\nSe o usuário quiser ação, oriente o formato:\n• "lançar despesa R$ 100 descrição"\n• "gerar código KING-NOME"\n• "status" ou "diagnóstico"\n\nSite: https://www.conectaking.com.br\nNão invente preços. Não invente dados financeiros. Respostas curtas (máx. ~1200 caracteres).`;

let msg = '';
try {
  if (intent === 'diag') {
    const h = await ck.call(this, 'GET', '/health');
    msg = 'Diagnóstico Conecta King\nHTTP ' + h.statusCode + '\n' + JSON.stringify(h.body).slice(0, 400);
  } else if (intent === 'finance') {
    if (!token) msg = 'CK_AGENT_JWT não configurado.';
    else if (!prev.amount || !(prev.amount > 0)) msg = 'Não entendi o valor. Ex.: "lançar despesa R$ 100 contas para pagar"';
    else {
      const body = {
        type: prev.type || 'EXPENSE',
        amount: Number(prev.amount),
        description: prev.description || 'Lançamento via Telegram',
        transaction_date: prev.transactionDate,
        status: prev.status || 'PENDING',
      };
      const r = await ck.call(this, 'POST', '/api/finance/transactions', body);
      if (r.statusCode >= 200 && r.statusCode < 300) {
        const row = (r.body && r.body.data) || {};
        msg = 'Lançamento criado na Gestão Financeira.\n' +
          (body.type === 'INCOME' ? 'Receita' : 'Despesa') + ': R$ ' + body.amount.toFixed(2) +
          '\nStatus: ' + body.status +
          '\nDesc: ' + body.description +
          (row.id ? '\nID: ' + row.id : '');
      } else msg = 'Falha ao lançar (' + r.statusCode + '): ' + JSON.stringify(r.body).slice(0, 300);
    }
  } else if (intent === 'code') {
    if (!token) msg = 'CK_AGENT_JWT não configurado.';
    else if (!prev.customCode) msg = 'Informe o código. Ex.: "gerar código KING-TESTTELE"';
    else {
      const r = await ck.call(this, 'POST', '/api/admin/codes/generate-manual', { customCode: prev.customCode, expiresAt: null });
      if (r.statusCode >= 200 && r.statusCode < 300) msg = 'Código criado: ' + prev.customCode;
      else msg = 'Falha ao criar código (' + r.statusCode + '): ' + JSON.stringify(r.body).slice(0, 300);
    }
  } else {
    const ai = await openaiChat.call(this, ADMIN_SYSTEM, 'Nome: ' + (prev.firstName || 'Admin') + '\nMensagem: ' + (prev.text || ''));
    msg = ai || ('Assistente Executivo online (sem OPENAI_API_KEY).\nComandos: status | lançar despesa R$ X ... | gerar código KING-XXXX');
  }
} catch (e) {
  msg = 'Erro ao executar: ' + String(e.message || e).slice(0, 300);
}

return [{ json: { ...prev, outMessage: msg } }];

const prev = $input.first().json;
const openaiKey = String($env.OPENAI_API_KEY || '').trim();
const model = String($env.OPENAI_MODEL || 'gpt-4o-mini').trim();
const name = prev.firstName || 'olá';
const text = String(prev.text || '').trim();

const CLIENT_SYSTEM = `Você é o Assistente do Conecta King no Telegram.\nAtenda clientes com cordialidade, clareza e português do Brasil.\n\nProduto: Conecta King — cartão virtual / link na bio / ferramentas para profissionais (fotógrafos etc.).\nSite: https://www.conectaking.com.br\nLogin: https://www.conectaking.com.br/login\n\nPode ajudar com: acesso/login/senha, o que é o Conecta King, como pedir código de ativação (só o King/admin libera), planos (sem inventar preço — mande ao site), suporte geral.\n\nSe pedirem falar com humano/King/pessoa, confirme que vai avisar o time e inclua na ÚLTIMA linha exatamente: ESCALATE:YES\nCaso contrário termine com: ESCALATE:NO\n\nRespostas curtas (máx. ~1200 caracteres). Não invente códigos, valores ou prazos.`;

let msg = '';
let escalate = /humano|falar com o king|atendente|pessoa/i.test(text);

try {
  if (!openaiKey) {
    msg = `Olá, ${name}! Sou o Assistente do Conecta King.\n\nPosso ajudar com acesso, planos e dúvidas.\nSite: https://www.conectaking.com.br\n\nPara atendimento humano, diga: falar com o King.`;
    if (/senha|login|acesso/i.test(text)) msg = 'Acesse: https://www.conectaking.com.br/login — use e-mail e senha do cadastro.';
    if (/plano|pre[cç]o|valor/i.test(text)) msg = 'Veja planos em https://www.conectaking.com.br — código de ativação o King libera no ADM.';
    if (escalate) msg = 'Certo! Vou avisar o time. Em breve alguém retorna.';
  } else {
    const r = await this.helpers.httpRequest.call(this, {
      method: 'POST',
      url: 'https://api.openai.com/v1/chat/completions',
      headers: {
        Authorization: 'Bearer ' + openaiKey,
        Accept: 'application/json',
        'Content-Type': 'application/json',
      },
      body: {
        model,
        temperature: 0.5,
        max_tokens: 550,
        messages: [
          { role: 'system', content: CLIENT_SYSTEM },
          { role: 'user', content: 'Nome do cliente: ' + name + '\nMensagem: ' + text },
        ],
      },
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
    });
    if (r.statusCode >= 200 && r.statusCode < 300) {
      let content = String(r.body?.choices?.[0]?.message?.content || '').trim();
      if (/ESCALATE:\s*YES/i.test(content)) escalate = true;
      content = content.replace(/\n?ESCALATE:\s*(YES|NO)\s*$/i, '').trim();
      msg = content || `Olá, ${name}! Como posso ajudar?`;
    } else {
      msg = 'Estou com instabilidade na IA agora. Tente de novo ou diga "falar com o King".';
    }
  }
} catch (e) {
  msg = 'Falha temporária no atendimento. Digite "falar com o King" para aviso humano.';
}

return [{ json: { ...prev, outMessage: msg, escalate: !!escalate } }];
